internal object Az305Mock6 {
    val quiz: Quiz = Quiz(
        id = "sa-mock-5", title = "AZ-305 mock exam 5", passPercent = 70, timeLimitMinutes = 100, instantFeedback = false, drawCount = 50,
        questions = B.spread(listOf(
            // Identity, governance and monitoring: logging and monitoring
            B.q("sa-m5-1", "sa-monitoring", "Investigators need two years of records of who created, changed or deleted Azure resources, searchable with KQL next to the resource logs. What do you recommend?", listOf("A diagnostic setting on each subscription sending the activity log to the Log Analytics workspace", "Diagnostic settings on each resource that send resource logs to the Log Analytics workspace", "Raise the activity log retention to two years in the subscription's activity log settings", "A monthly CSV export of the activity log from the portal, kept in a Blob Storage container"), setOf(0), "The activity log records control-plane actions such as create, change and delete, but keeps them only for 90 days. A subscription diagnostic setting sends it to a workspace, where it is kept as long as you set and queried alongside other logs.",
                scenario = "Elderberry Bank's security team investigates incidents in the subscriptions behind its Android banking app. Last month the trail they needed was older than 90 days and had gone.",
                whyWrong = mapOf(
                    1 to "Resource logs record operations inside a resource, such as reads of a key vault, not the creation, change or deletion of resources, which the activity log records.",
                    2 to "The activity log's own retention is fixed at 90 days and cannot be raised; keeping it longer means sending it elsewhere with a diagnostic setting.",
                    3 to "CSV files in a blob container cannot be queried with KQL next to the resource logs, and a monthly manual export is easy to miss.",
                ),
            ),
            B.q("sa-m5-2", "sa-monitoring", "The team must be alerted when its own production database becomes unavailable, whether the cause is an Azure platform problem or something else, and told when it recovers. What do you recommend?", listOf("A Resource Health alert on the database", "A Service Health alert on the region", "A budget alert", "An Azure Advisor recommendation"), setOf(0), "Resource Health reports the health of your individual resources, such as one database, and why it is unavailable. A Resource Health alert fires when that resource's health changes, including when it recovers.",
                scenario = "Ospreay Delivery's Android courier app stops when its Azure SQL database is unavailable. Service Health alerts cover region-wide incidents, but last week the database alone was down and nobody was told.",
                whyWrong = mapOf(
