            ),
            B.q("sa-m5-3", "sa-monitoring", "Application Insights telemetry from a very busy API costs too much, but the charts must still show accurate request rates and failure trends. What do you recommend?", listOf("Turn on sampling in Application Insights", "Turn off Application Insights", "Log only failures and nothing else", "Send the telemetry to a storage account"), setOf(0), "Sampling keeps a representative share of telemetry and adjusts the counts, so charts still show accurate rates and trends while far less data is stored and billed. Related items of one request are kept or dropped together.",
                scenario = "Gullhaven's Android social app makes 50,000 API calls a second at peak. The Application Insights bill now exceeds the compute bill.",
                whyWrong = mapOf(
                    1 to "Turning it off leaves the team blind.",
                    2 to "Logging only failures loses the request rates and response times the charts need.",
                    3 to "Storage is not a monitoring tool, and the app would still produce the same volume.",
                ),
            ),
            B.q("sa-m5-4", "sa-monitoring", "A Log Analytics workspace steadily ingests about 300 GB a day, billed at the pay-as-you-go price. How do you lower the cost without collecting less?", listOf("Choose a commitment tier that matches the daily volume", "Set a daily cap of 100 GB to limit the billed ingestion", "Split the data across three workspaces of 100 GB a day", "Lower the analytics retention of every table to seven days"), setOf(0), "Commitment tiers, starting at 100 GB a day, give a lower price per gigabyte in exchange for committing to a daily volume. At a steady 300 GB a day, a matching tier costs noticeably less than pay-as-you-go.",
                scenario = "Kinsale Telecom collects logs from the systems behind its Android account app into one workspace. Volume is steady and nothing can be dropped.",
