            // Identity
            B.q("sa-m5-5", "sa-identity", "Staff already carry smart cards with X.509 certificates from the company's own certificate authority, and should use them to sign in to Microsoft Entra ID, without AD FS. What do you recommend?", listOf("Microsoft Entra certificate-based authentication", "Pass-through authentication with on-premises agents", "Windows Hello for Business with cloud Kerberos trust", "Federation through AD FS for the smart card users"), setOf(0), "Microsoft Entra certificate-based authentication lets users sign in with X.509 certificates, such as those on smart cards, directly against Entra ID. It is phishing-resistant and needs no federation server.",
                scenario = "Albion Defence Logistics issues smart cards to all staff. It is retiring AD FS, and its Android stock app and Microsoft 365 must keep smart card sign-in.",
                whyWrong = mapOf(
