            B.q("sa-m5-8", "sa-identity", "Everyone in the Sales department must automatically get access to the sales apps, and lose it when they move department, based on the department attribute. What do you recommend?", listOf("A dynamic membership group with a rule on the department attribute", "An assigned security group that HR updates when people move", "A dynamic administrative unit with a rule on the department attribute", "A Conditional Access policy that targets users by department"), setOf(0), "A dynamic membership group adds and removes users automatically by a rule on their attributes, such as department equals Sales. Apps assigned to the group follow membership changes.",
                scenario = "Tamarind Foods' 400 sales staff use a dedicated Android ordering app. People move departments often, and IT forgets to update the group.",
