            // Authorization and secrets
            B.q("sa-m5-9", "sa-authorization", "An AKS cluster must pull images from Azure Container Registry with no registry password stored anywhere. What do you recommend?", listOf("Grant the cluster's kubelet managed identity the AcrPull role on the registry", "Turn on the registry's admin user and store its password in a Kubernetes secret", "Make the registry public", "Give the cluster Owner on the registry"), setOf(0), "The kubelet identity is the managed identity AKS nodes use. Granting it AcrPull lets nodes pull images using Entra tokens, with no password, and with the least access needed.",
                scenario = "Thistledown's Android delivery app runs on AKS. A registry password was found in a Git history, and security wants no more registry credentials.",
                whyWrong = mapOf(
