            B.q("sa-m5-11", "sa-authorization", "Apps must read and write Cosmos DB items using Microsoft Entra identities only, and account keys must stop working. What do you configure? Select two.", listOf("Assign Cosmos DB data-plane roles, such as the built-in data contributor role, to the apps' managed identities", "Disable key-based (local) authentication on the account", "Give the apps the Contributor role on the account", "Rotate the primary key every week"), setOf(0, 1), "Cosmos DB has its own data-plane roles for reading and writing items, granted to Entra identities. Disabling local authentication turns off the account keys, so only those identities can reach the data.",
                scenario = "Bramblegate Games' Android game saves progress in Cosmos DB. An account key ended up in a public repository, and security wants keys gone for good.",
                whyWrong = mapOf(
