            B.q("sa-m5-12", "sa-authorization", "Hybrid users on Microsoft Entra-joined laptops, with no line of sight to a domain controller, must open Azure Files shares with their identities and existing permissions. What do you recommend?", listOf("Microsoft Entra Kerberos authentication for Azure Files", "Mount the share with the storage account key", "A VPN so every laptop can reach a domain controller", "Anonymous access to the share"), setOf(0), "With Microsoft Entra Kerberos, Entra ID issues the Kerberos tickets for Azure Files, so hybrid users on Entra-joined devices can open shares without reaching a domain controller, while Windows permissions still apply.",
                scenario = "Hesketh Architects' staff work from home on Entra-joined laptops and upload drawings from the Android site app. The office VPN is being switched off.",
                whyWrong = mapOf(
