            // Governance
            B.q("sa-m5-13", "sa-governance", "The Environment tag must be present on every resource group and may only be Prod, Test or Dev. Anything else must be refused at creation. What do you recommend?", listOf("An Azure Policy with the deny effect that checks the tag against a list of allowed values", "An Azure Policy with the audit effect that checks the tag against a list of allowed values", "An Azure Policy with the modify effect that adds Environment set to Prod when it is missing", "A CanNotDelete lock on each subscription so that existing tags cannot be removed"), setOf(0), "A policy with the deny effect is evaluated at creation and update, and refuses requests that break its rule. With a parameter listing allowed values, it blocks missing tags and typos such as Prd.",
                scenario = "Bellingham Bus's cost reports for its Android ticket app are wrong because Environment tags read Prod, prod, Production and PRD.",
                whyWrong = mapOf(
                    1 to "Audit marks wrong tags as non-compliant after the fact; it does not refuse them at creation.",
