                    1 to "A VM is infrastructure to manage, and its data does not sit in the lake.",
                    2 to "Table storage is key-value storage, not a warehouse.",
                    3 to "File shares have no query engine.",
                ),
            ),
            B.q("sa-m5-29", "sa-data-integration", "Data Factory pipelines must be versioned in Git, reviewed, and promoted from development to test to production automatically. What do you recommend?", listOf("Git integration on the development factory, with CI/CD releases to test and production factories", "Git integration on every factory, with changes made and published in each one directly", "One factory with Git integration and a separate folder of pipelines for each environment", "Export each factory's ARM template from the portal and import it into the next by hand"), setOf(0), "Data Factory integrates with Git for the development factory. Published changes produce templates that a CI/CD pipeline, such as GitHub Actions or Azure Pipelines, deploys to separate test and production factories.",
                scenario = "Cormorant Insurance's data team broke production twice by editing pipelines feeding its Android claims app directly in the portal.",
                whyWrong = mapOf(
                    1 to "Editing and publishing in each factory still changes production by hand; Microsoft recommends Git on the development factory with automated releases onward.",
                    2 to "One factory mixes environments, so a test change can hit production.",
                    3 to "Manual export and import is error-prone, untracked and not automatic promotion.",
                ),
            ),
            B.q("sa-m5-30", "sa-data-integration", "Existing producers use Apache Kafka client libraries, and the company wants a managed Azure service to receive their streams without changing the clients' code. What do you recommend?", listOf("Azure Event Hubs in the Standard tier or higher", "Azure Service Bus in the Premium tier, with topics", "Azure IoT Hub in the Standard tier or higher", "Azure Queue Storage in a general-purpose v2 account"), setOf(0), "Event Hubs exposes an Apache Kafka-compatible endpoint. Kafka producers and consumers connect by changing configuration, such as the server address and credentials, not code.",
                scenario = "Lorimer Telematics' devices and its Android fleet app stream events with Kafka clients to a Kafka cluster the team no longer wants to run.",
                whyWrong = mapOf(
                    1 to "Service Bus speaks AMQP, not the Kafka protocol, so the Kafka clients would have to be rewritten.",
                    2 to "IoT Hub takes device messages over MQTT, AMQP or HTTPS, not from Kafka producer clients.",
                    3 to "Queue Storage takes messages through its own REST API, not the Kafka protocol, so the Kafka clients would have to be rewritten.",
                ),
            ),
            // Business continuity: backup and disaster recovery
            B.q("sa-m5-31", "sa-backup-dr", "An Azure Database for PostgreSQL flexible server must be restorable in another region if its own region is lost. What must you choose, and when?", listOf("Geo-redundant backup storage, chosen when the server is created", "Locally redundant backups, changed later if needed", "A longer retention period", "A read replica in the same region"), setOf(0), "Flexible server keeps automated backups for 7 to 35 days. Geo-redundant backup storage copies them to the paired region for geo-restore, and it can only be chosen when the server is created.",
                scenario = "Strathmore Clinics is creating the PostgreSQL server for its new Android booking app. It needs a way to recover if the whole region fails.",
                whyWrong = mapOf(
                    1 to "Backup redundancy cannot be changed to geo-redundant after creation.",
                    2 to "Longer retention keeps backups longer, still in one region.",
                    3 to "A replica in the same region is lost with the region.",
                ),
            ),
            B.q("sa-m5-32", "sa-backup-dr", "SAP HANA databases on Azure VMs need application-consistent backups with log backups, managed from Azure, without a third-party tool. What do you recommend?", listOf("Azure Backup for SAP HANA in Azure VMs, to a Recovery Services vault", "Azure VM backup with pre and post scripts, to a Recovery Services vault", "Azure Disk Backup of the HANA data disks, to a Backup vault", "Azure Site Recovery with app-consistent recovery points"), setOf(0), "Azure Backup integrates with SAP HANA through its certified Backint interface. It takes full, differential and log backups into a Recovery Services vault and restores to a point in time.",
                scenario = "Hartley Steel's SAP HANA system, which feeds stock levels to its Android sales app, moved to Azure VMs. The old backup tool's licence ends next month.",
                whyWrong = mapOf(
                    1 to "VM backup with scripts can make a consistent snapshot, but it takes no HANA log backups, so there is no point-in-time restore between snapshots.",
                    2 to "Disk snapshots are crash-consistent for HANA and take no log backups.",
                    3 to "Site Recovery replicates for DR; it keeps no long backup history or HANA log backups.",
                ),
            ),
            B.q("sa-m5-33", "sa-backup-dr", "The AKS-hosted API is stateless, and its data lives in a geo-replicated database. How should it be recovered in another region with the least standing cost?", listOf("Redeploy the cluster and workloads from infrastructure as code and GitOps when needed", "Keep a smaller standby cluster running in the second region, synced by GitOps", "Back up the node VMs daily and restore them in the second region when needed", "Replicate the node VMs to the second region with Azure Site Recovery"), setOf(0), "For stateless workloads, the code and configuration are the recovery source. Bicep or Terraform recreates the cluster, and GitOps redeploys the workloads, while the data comes from the replicated database. Nothing runs until needed.",
                scenario = "Calloway Cinemas' Android booking API runs on AKS and keeps no state in the cluster. Its RTO is four hours, and the budget for idle DR resources is small.",
                whyWrong = mapOf(
                    1 to "A warm standby recovers faster than the four-hour RTO needs, but it costs money every day, so it is not the least standing cost.",
                    2 to "Node VMs are disposable and managed by AKS; restoring them does not recover a working cluster.",
                    3 to "AKS nodes are created and replaced by the cluster, so they are not a Site Recovery workload, and replication would add standing cost anyway.",
                ),
            ),
            B.q("sa-m5-34", "sa-backup-dr", "A whole Azure file share was deleted by mistake an hour ago. What should have been enabled so it can be undeleted?", listOf("Soft delete for file shares", "Blob versioning", "A CanNotDelete lock on a resource group in another subscription", "Geo-redundant storage"), setOf(0), "Soft delete for Azure file shares keeps a deleted share, with its snapshots, for a retention period. Within that period it can be undeleted.",
                scenario = "An administrator at Dunstan Print deleted the share that holds artwork for its Android print-ordering app while cleaning up test shares.",
                whyWrong = mapOf(
                    1 to "Versioning is a Blob Storage feature, not Azure Files.",
                    2 to "A lock elsewhere does nothing for this share.",
                    3 to "Geo-redundancy copies the deletion too.",
                ),
            ),
            B.q("sa-m5-35", "sa-backup-dr", "A user needs one configuration file back from last Tuesday's backup of a Windows VM, without restoring the whole VM. What do you do?", listOf("Use file recovery from the VM's recovery point to mount it and copy the file", "Restore the VM as a new VM from last Tuesday's recovery point and copy the file", "Replace the VM's existing disks with those from last Tuesday's recovery point", "Fail over with Site Recovery to the recovery point taken last Tuesday"), setOf(0), "Azure Backup's file recovery mounts a recovery point's disks as drives, so you can browse and copy individual files, then unmount. The VM is not restored.",
                scenario = "An engineer at Fairhaven Logistics overwrote the config file of the API behind its Android tracking app. The VM is backed up nightly by Azure Backup.",
                whyWrong = mapOf(
                    1 to "Creating a whole new VM for one file is slow and wasteful, which is what the user wants to avoid.",
                    2 to "Replacing the disks rolls the whole VM back to Tuesday, undoing every change since.",
                    3 to "Site Recovery failover moves the whole VM for disasters, and this VM is protected by Azure Backup, not Site Recovery.",
                ),
            ),
            B.q("sa-m5-36", "sa-backup-dr", "The team must be told at once when any backup job fails across all vaults, through its existing action groups. What do you recommend?", listOf("Azure Monitor alerts for Azure Backup, with an alert processing rule", "Classic alerts in each Recovery Services vault, with email notifications", "Backup reports in a Log Analytics workspace, reviewed each morning", "A Resource Health alert on each Recovery Services vault"), setOf(0), "Azure Backup raises built-in alerts in Azure Monitor, such as for failed jobs. Alert processing rules or alert rules route them to action groups, so the same channels notify the team.",
                scenario = "Elmhurst Housing found its backups for the Android repairs app had failed for nine days before anyone noticed.",
                whyWrong = mapOf(
                    1 to "Classic vault alerts notify through their own email setting, not action groups, and Microsoft recommends moving to Azure Monitor alerts.",
                    2 to "A daily review is how nine days went by unnoticed; reports are not alerts.",
                    3 to "Resource Health says whether the vault itself is available, not whether backup jobs failed.",
                ),
            ),
            // Business continuity: high availability
            B.q("sa-m5-37", "sa-high-availability", "App Service sometimes leaves one bad instance running that returns errors. Traffic must stop going to it automatically. What do you configure?", listOf("The App Service health check, pointing at a health endpoint", "ARR affinity, so each user stays on an instance that works", "Autoscale rules that add an instance when errors increase", "An Application Insights availability test on the app's URL"), setOf(0), "The health check feature calls a path on each instance. Instances that keep failing are taken out of the load balancer's rotation, and replaced if they stay unhealthy, so users stop hitting them.",
                scenario = "Kenwood Taxis' Android booking API runs on five App Service instances. Now and then one hangs, and a fifth of bookings fail until someone restarts it.",
                whyWrong = mapOf(
                    1 to "ARR affinity pins users to an instance, so those pinned to the bad one keep failing, and nothing removes it.",
                    2 to "Adding instances leaves the bad one in rotation, still getting its share of traffic.",
                    3 to "An availability test checks the site from outside and can alert, but it takes no instance out of rotation.",
                ),
            ),
            B.q("sa-m5-38", "sa-high-availability", "A PostgreSQL flexible server needs a copy in another region that can be turned into a writable server if the primary region fails. What do you configure?", listOf("A cross-region read replica, promoted when needed", "Same-zone high availability", "A longer backup retention", "An extra database on the same server"), setOf(0), "A cross-region read replica is kept up to date asynchronously. In a regional outage you promote it to a standalone, writable server and point the app at it.",
                scenario = "Tolland Transit's timetable database for its Android journey planner is on PostgreSQL flexible server. A regional outage last year stopped it for a day.",
                whyWrong = mapOf(
                    1 to "Same-zone HA stays in one data centre of one region.",
                    2 to "Retention changes how long backups are kept, not where they are.",
                    3 to "Another database on the same server fails with it.",
                ),
            ),
            B.q("sa-m5-39", "sa-high-availability", "An API on AKS must keep running if an entire Azure region fails. What do you recommend? Select two.", listOf("Run an AKS cluster in each of two regions", "Put Azure Front Door in front of both clusters with health probes", "Add more nodes to the existing cluster", "Use a single cluster with the Free tier"), setOf(0, 1), "A cluster in each region removes the single region as a point of failure. Front Door probes both and sends users only to healthy ones, so a regional outage just moves traffic.",
                scenario = "Wexford Bank's Android payments API runs on one AKS cluster. Its regulator now requires survival of a regional outage.",
                whyWrong = mapOf(
                    2 to "More nodes in one region still fail with the region.",
                    3 to "The Free tier has no SLA and is still one region.",
                ),
            ),
            B.q("sa-m5-40", "sa-high-availability", "A Hyperscale database must survive a data centre failure with fast automatic failover. What do you configure?", listOf("Zone redundancy with at least one high-availability replica", "Two high-availability replicas, without zone redundancy", "Named replicas configured in two other availability zones", "Geo-redundant backup storage, used for a geo-restore"), setOf(0), "Hyperscale high-availability replicas are ready copies of the compute that take over if the primary fails. With zone redundancy they sit in other availability zones, so a data centre failure is survived quickly.",
                scenario = "Aldwick Media's Hyperscale database for its Android news app runs with no replicas. A zone failure would take it offline.",
                whyWrong = mapOf(
                    1 to "Without zone redundancy, failover happens within the same data centre, so a data centre failure can take the replicas down too.",
                    2 to "Named replicas serve reads; they are not failover targets for the primary.",
                    3 to "Geo-restore rebuilds the database from backup, which is slow and loses recent changes.",
                ),
            ),
            B.q("sa-m5-41", "sa-high-availability", "Two clustered VMs in different availability zones need one shared data disk that survives a zone failure. What do you recommend?", listOf("A zone-redundant (ZRS) managed disk, used as a shared disk", "A locally redundant (LRS) Premium SSD, used as a shared disk", "A zone-redundant Ultra Disk, used as a shared disk", "A ZRS blob container mounted on both nodes with BlobFuse"), setOf(0), "ZRS managed disks copy data across three availability zones. As a shared disk they can be attached to VMs in different zones, so a clustered app keeps its data when one zone fails.",
                scenario = "Westbury Steel runs a two-node failover cluster for the database behind its Android plant-monitoring app. Each node is in its own zone, and they need one shared disk.",
                whyWrong = mapOf(
                    1 to "An LRS disk lives in one zone and fails with it.",
                    2 to "Ultra Disks do not support ZRS; zone-redundant managed disks are Premium SSD or Standard SSD.",
                    3 to "BlobFuse mounts blobs as files; it is not a shared block disk that a failover cluster can use.",
                ),
            ),
            // Infrastructure: compute
            B.q("sa-m5-42", "sa-compute", "The company has standardised on Red Hat OpenShift on-premises and wants the same platform as a managed service in Azure, jointly supported by Microsoft and Red Hat. What do you recommend?", listOf("Azure Red Hat OpenShift", "Azure Container Instances", "Azure App Service", "Azure Functions"), setOf(0), "Azure Red Hat OpenShift is a managed OpenShift service run jointly by Microsoft and Red Hat. Teams keep their OpenShift tools and workflows.",
                scenario = "Granton Bank runs its Android app back end on OpenShift on-premises. Its platform team wants to move to Azure without retraining.",
                whyWrong = mapOf(
                    1 to "Container Instances runs single containers, not an OpenShift platform.",
                    2 to "App Service hosts web apps, not OpenShift.",
                    3 to "Functions runs serverless code, not OpenShift.",
                ),
            ),
            B.q("sa-m5-43", "sa-compute", "A static marketing site for the Android app needs global hosting, free TLS, preview environments for pull requests and a small serverless API. What do you recommend?", listOf("Azure Static Web Apps", "A VM running IIS", "Azure Kubernetes Service", "Azure Batch"), setOf(0), "Azure Static Web Apps hosts static front ends globally, with free TLS certificates, preview environments for each pull request and an integrated Azure Functions API.",
                scenario = "Puffin Puzzles needs a landing page and sign-up form for its new Android game. The team is two people with no ops time.",
                whyWrong = mapOf(
                    1 to "A VM is a server to run and patch.",
                    2 to "AKS is far too much for a static site.",
                    3 to "Batch is for compute jobs, not websites.",
                ),
            ),
            B.q("sa-m5-44", "sa-compute", "Batch-style pods on AKS can be interrupted and should run as cheaply as possible, while system pods stay on regular nodes. What do you recommend?", listOf("Add a separate user node pool of Spot VMs for the batch pods", "Convert the system node pool to Spot VMs and run the batch pods there", "Cap the cluster autoscaler at fewer nodes on the regular node pool", "Three-year reserved instances for the regular node pool"), setOf(0), "AKS supports Spot node pools as user pools. Interruptible workloads run there cheaply, using taints and tolerations, while system pods stay on a regular system pool, which cannot use Spot.",
                scenario = "Nightjar Analytics runs nightly report jobs for its Android dashboard app on AKS. They tolerate restarts, and the cluster bill is growing.",
                whyWrong = mapOf(
                    1 to "System node pools cannot use Spot VMs, and evicting them would break the cluster.",
                    2 to "Fewer regular nodes still cost full price and make the jobs run longer.",
                    3 to "Reservations pay for nodes around the clock for a nightly workload and do not use the jobs' tolerance of interruption, as Spot pricing does.",
                ),
            ),
            B.q("sa-m5-45", "sa-compute", "Six small, low-traffic web apps each run on their own App Service plan. How do you cut cost without changing the apps?", listOf("Host them together on one App Service plan sized for their combined load", "Buy reserved instances for each of the six Standard App Service plans", "Turn on autoscale on each plan with a minimum of one instance", "Move all six apps into one App Service Environment to share it"), setOf(0), "An App Service plan is the set of VMs you pay for, and several apps can share one plan. Putting small apps together means paying for one plan instead of six.",
                scenario = "Hollis Vets runs six small admin sites, including one for its Android booking app, each on its own Standard plan and mostly idle.",
                whyWrong = mapOf(
                    1 to "App Service reserved instances apply only to Premium v3 or later and Isolated v2 or later plans, not Standard.",
                    2 to "Each plan already runs one instance, so autoscale saves nothing; six plans are still paid for.",
                    3 to "Apps in an App Service Environment run on Isolated v2 plans, which cost more per instance than Standard, so this costs more than one shared Standard plan and means redeploying every app.",
                ),
            ),
            B.q("sa-m5-46", "sa-compute", "Each night, 500 independent tasks each need several hours of CPU on VMs with licensed software installed, and the pool should grow and shrink automatically. What do you recommend?", listOf("Azure Batch with a custom image and an autoscale formula on the pool", "Azure Functions on the Consumption plan, fanned out with Durable Functions", "A virtual machine scale set with the software installed and CPU autoscale", "An Azure Logic App with a For each loop that starts every model run"), setOf(0), "Azure Batch schedules many independent tasks across a pool of VMs, which can use a custom image with your software and an autoscale formula. It suits long, CPU-heavy parallel work.",
                scenario = "Kestrel Actuarial runs risk models every night for the figures in its Android advisor app. Each model takes three hours of CPU.",
                whyWrong = mapOf(
                    1 to "Consumption plan functions stop after 10 minutes at most, and each fanned-out activity has the same limit.",
                    2 to "A scale set can grow and shrink, but it has no job scheduler; queuing, assigning and retrying 500 tasks would have to be built.",
                    3 to "Logic Apps orchestrates workflows; it has no compute to run hours of CPU work.",
                ),
            ),
            // Infrastructure: application architecture
            B.q("sa-m5-47", "sa-app-architecture", "Thousands of IoT devices must publish and subscribe to messages over MQTT through a managed broker, with events also routed to Azure services. What do you recommend?", listOf("An Azure Event Grid namespace with topic spaces", "Azure Service Bus Premium topics and subscriptions", "Azure Event Hubs with a consumer group for each subscriber", "Azure Event Grid custom topics with push delivery"), setOf(0), "Event Grid namespaces include an MQTT broker. Devices publish and subscribe over MQTT, a lightweight messaging protocol, and messages can be routed on to other Azure services.",
                scenario = "Glowworm Lighting's smart bulbs talk MQTT, and its Android app controls them. The company's self-run MQTT broker crashes under load.",
                whyWrong = mapOf(
                    1 to "Service Bus uses AMQP, not MQTT, for publishing and subscribing.",
                    2 to "Event Hubs offers no MQTT endpoint, and consumer groups let services read a stream; devices cannot publish and subscribe to topics through them.",
                    3 to "Custom topics take events over HTTPS and push them to handlers; devices cannot publish and subscribe over MQTT there.",
                ),
            ),
            B.q("sa-m5-48", "sa-app-architecture", "Whenever a resource is created or deleted in a subscription, an automation must run within seconds, without polling. What do you recommend?", listOf("An Event Grid system topic for the subscription that triggers a function", "An Event Grid custom topic that Resource Manager publishes resource events to", "An hourly Azure Resource Graph query for resources created since the last run", "An Azure Policy with the auditIfNotExists effect that starts a function"), setOf(0), "Azure publishes resource events, such as create and delete, to Event Grid. A system topic for the subscription with an event subscription pushes them to a handler, such as a function, within seconds.",
                scenario = "Torrent Media wants every new resource in its Android app subscriptions to be logged in its CMDB the moment it is created.",
                whyWrong = mapOf(
                    1 to "Azure services publish their events to system topics; custom topics are for your own applications to publish to.",
                    2 to "Hourly polling is late and misses the within-seconds requirement.",
                    3 to "Policy effects audit, deny or change resources; auditIfNotExists only marks resources non-compliant and cannot start a function.",
                ),
            ),
            B.q("sa-m5-49", "sa-app-architecture", "A breaking change to an API is coming, but older Android app versions in the field must keep calling the old contract for a year. What do you recommend in API Management?", listOf("Publish the new contract as a new API version, such as /v2 in the path, keeping v1", "Add the new contract as a revision of the API and make that revision current", "Change the existing API in place and announce the change in the release notes", "Block old app versions with a check-header policy so users must update"), setOf(0), "API Management versions let you publish breaking changes side by side, such as /v1 and /v2, so old clients keep working. Revisions are for non-breaking changes to the same version.",
                scenario = "Sandpiper Bank's Android app is updated slowly by its customers. Old versions must keep working while new ones use a redesigned payments API.",
                whyWrong = mapOf(
                    1 to "A revision replaces the current contract for everyone when made current, so it suits only non-breaking changes.",
                    2 to "Changing in place breaks every old app at once, whatever the notes say.",
                    3 to "Blocking old apps cuts off customers who have not updated, which the year of support rules out.",
                ),
            ),
            B.q("sa-m5-50", "sa-app-architecture", "App Configuration must keep serving settings if its primary region has an outage, with replicas close to apps in other regions. What do you recommend?", listOf("Geo-replication of the App Configuration store into the other regions", "A snapshot of the store that the apps load when West Europe is down", "A second store in each region, refreshed by a manual export and import", "The store's availability zone support in West Europe, with no extra stores"), setOf(0), "App Configuration geo-replication adds replicas of a store in other regions. Apps can read from the nearest replica and fail over to another if one region is unavailable.",
                scenario = "Juniper Air's Android check-in API runs in three regions and reads settings and feature flags from one App Configuration store in West Europe.",
                whyWrong = mapOf(
                    1 to "Snapshots are kept in the same store, so they are unavailable when its region is down.",
                    2 to "Manual copies drift and fail when people forget.",
                    3 to "Zone redundancy survives a data centre failure, not a regional outage, and puts no replica near the other regions.",
                ),
            ),
            B.q("sa-m5-51", "sa-app-architecture", "Many AKS clusters must have their workloads deployed from a Git repository automatically, with drift corrected back to what Git says. What do you recommend?", listOf("GitOps with the Flux extension installed on each cluster", "A GitHub Actions workflow that runs kubectl apply on every push", "Azure Policy for AKS with the manifests as policy definitions", "The AKS automatic upgrade channel set to stable on each cluster"), setOf(0), "With GitOps, Git holds the desired state. The Flux extension on each cluster pulls changes from the repository, applies them, and reverts changes made outside Git.",
                scenario = "Ravenglass Telecom runs 12 AKS clusters for its Android apps. Engineers make manual changes, and no two clusters match.",
                whyWrong = mapOf(
                    1 to "A pipeline pushes changes when Git changes, but nothing corrects manual changes made in between, so drift remains.",
                    2 to "Azure Policy for AKS audits or denies settings; it does not deploy workloads from Git.",
                    3 to "The upgrade channel keeps Kubernetes versions current; it does not deploy workloads.",
                ),
            ),
            // Infrastructure: migrations
            B.q("sa-m5-52", "sa-migrations", "Before and after migrating a workload, the architects want to check its design against reliability, security, cost, operational excellence and performance best practice. What do you use?", listOf("An Azure Well-Architected Review assessment of the workload", "Azure Advisor recommendations for the target subscription", "Microsoft Defender for Cloud secure score for the workload", "An Azure Migrate assessment of the workload's servers"), setOf(0), "The Azure Well-Architected Framework sets out five pillars: reliability, security, cost optimisation, operational excellence and performance efficiency. The Well-Architected Review asks questions about a workload and gives recommendations for each pillar.",
                scenario = "Southfield Energy is moving the back end of its Android meter app to Azure and wants an independent check that the target design is sound.",
                whyWrong = mapOf(
                    1 to "Advisor checks resources already deployed in Azure, so it cannot review the design before migration, and it reviews resource settings rather than the workload's architecture.",
                    2 to "Secure score covers security only, one of the five pillars.",
                    3 to "An Azure Migrate assessment covers readiness, sizing and cost for the move, not a review against all five pillars.",
                ),
            ),
            B.q("sa-m5-53", "sa-migrations", "Two hundred Hyper-V VMs must be discovered and assessed for Azure, including performance data for right-sizing. What do you recommend?", listOf("Deploy the Azure Migrate appliance for Hyper-V and run an assessment", "Deploy the Azure Migrate appliance for VMware, pointed at the Hyper-V hosts", "Azure Monitor VM insights with the agent installed on each Hyper-V host", "Connect the VMs to Azure Arc and use Azure Advisor right-sizing"), setOf(0), "The Azure Migrate appliance for Hyper-V discovers VMs and collects their configuration and performance data. Assessments then recommend Azure VM sizes and costs based on real use.",
                scenario = "Ellesmere Health runs Hyper-V in two data centres, including the back end of its Android patient app, and must plan the move to Azure.",
                whyWrong = mapOf(
                    1 to "The VMware appliance discovers through vCenter Server; Hyper-V needs the Hyper-V appliance.",
                    2 to "VM insights monitors machine performance; it does not assess machines for Azure sizes and costs.",
                    3 to "Advisor's resize recommendations cover Azure VMs and scale sets, not servers still on-premises, so this gives no Azure sizing or migration cost.",
                ),
            ),
            B.q("sa-m5-54", "sa-migrations", "Three hundred terabytes must reach Azure over a slow link, and the office keeps changing files during the weeks of transfer. What approach do you recommend? Select two.", listOf("Seed the bulk of the data offline with Azure Data Box", "Copy the changes made since the seed online, for example with AzCopy, before cutover", "Copy everything online over the slow link", "Stop all work in the office for two months"), setOf(0, 1), "A common pattern is to seed the bulk offline with Data Box, which is shipped to and from the Azure data centre, then copy only the changes made since then over the network before cutting over.",
                scenario = "Morwenna Films has 300 TB of footage for its Android streaming app on a NAS. Its 100 Mbps link would take most of a year, and editors keep working.",
                whyWrong = mapOf(
                    2 to "At 100 Mbps, 300 TB takes most of a year online.",
                    3 to "Stopping work for months is not acceptable to the business.",
                ),
            ),
            B.q("sa-m5-55", "sa-migrations", "A MySQL database must move to Azure Database for MySQL flexible server with only minutes of downtime at cutover. What do you recommend?", listOf("An online migration with Database Migration Service, syncing changes until cutover", "An offline migration with Database Migration Service, run in the quietest hour", "A mysqldump taken on Friday night and restored over the weekend", "Azure Site Recovery replication of the MySQL server VM, then failover"), setOf(0), "An online migration copies the data, then keeps applying changes from the source until you cut over. Downtime is only the few minutes needed to stop writes and switch the app.",
                scenario = "Wheatley Groceries' Android ordering app takes orders all day, every day, from a MySQL database on-premises.",
                whyWrong = mapOf(
                    1 to "An offline migration needs writes stopped for the whole copy, and the app takes orders all day, every day.",
                    2 to "A weekend dump and restore means the app is down for the whole copy.",
                    3 to "Site Recovery moves the VM with MySQL on it, not the database into a managed flexible server.",
                ),
            ),
            // Infrastructure: networks
            B.q("sa-m5-56", "sa-network-connectivity", "The company offers an API to business customers, who must reach it privately from their own VNets, without peering or exposing it to the internet. What do you recommend?", listOf("A Private Link service on a Standard Load Balancer, with private endpoints in customer VNets", "VNet peering with each customer's VNet, with NSG rules allowing just the API's port", "A private endpoint for the API in the company's own VNet, shared with each customer", "Azure Front Door Premium in front of the API, with a Private Link origin to the load balancer"), setOf(0), "A Private Link service exposes your service, behind a Standard Load Balancer, to other tenants. Each customer creates a private endpoint in their own VNet, so traffic stays private with no peering or overlapping address problems.",
                scenario = "Lattimer Payments sells its payments API, the same one its Android app uses, to banks. Banks refuse to send payment traffic over the internet.",
                whyWrong = mapOf(
                    1 to "Peering is ruled out; it connects whole networks and clashes on overlapping address ranges.",
                    2 to "A private endpoint sits in the VNet that consumes the service; one in the company's own VNet is unreachable to customers without peering or VPN.",
                    3 to "Front Door's Private Link runs from Front Door to the origin; customers would still reach Front Door over the internet.",
                ),
            ),
            B.q("sa-m5-57", "sa-network-connectivity", "Web VMs must serve users on the internet, but no VM may have its own public IP address. What do you recommend?", listOf("An Application Gateway with a public front end and the VMs in its back-end pool", "A NAT gateway on the VMs' subnet to accept the inbound web requests", "A public IP on each VM with an NSG allowing just ports 80 and 443", "Azure Bastion in the VNet, with users connecting through it to the site"), setOf(0), "Placing an Application Gateway, or a public load balancer, in front means only it has a public address. It forwards requests to VMs on private addresses, and the VMs are never directly reachable.",
